    wd_output.dumpable_momentum_nms.x = 0.0; wd_output.dumpable_momentum_nms.y = 0.0; wd_output.dumpable_momentum_nms.z = 0.0;
    wd_output.dipole_a_m2.x = 0.0; wd_output.dipole_a_m2.y = 0.0; wd_output.dipole_a_m2.z = 0.0;
    wd_output.torque_nm.x = 0.0; wd_output.torque_nm.y = 0.0; wd_output.torque_nm.z = 0.0;
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.saturation_mask = 0U;
    return;
}

// 3. Check Wheel Speeds
for (size_t i = 0; i < 4; ++i) {
    if (fabs(wd_input.wheels[i].speed_rad_s) > wd_config.max_wheel_speed_rad_s) {
        wd_state.mode = WD_FAULT;
        wd_output.momentum_nms.x = 0.0; wd_output.momentum_nms.y = 0.0; wd_output.momentum_nms.z = 0.0;
        wd_output.parallel_momentum_nms.x = 0.0; wd_output.parallel_momentum_nms.y = 0.0; wd_output.parallel_momentum_nms.z = 0.0;
        wd_output.dumpable_momentum_nms.x = 0.0; wd_output.dumpable_momentum_nms.y = 0.0; wd_output.dumpable_momentum_nms.z = 0.0;
        wd_output.dipole_a_m2.x = 0.0; wd_output.dipole_a_m2.y = 0.0; wd_output.dipole_a_m2.z = 0.0;
        wd_output.torque_nm.x = 0.0; wd_output.torque_nm.y = 0.0; wd_output.torque_nm.z = 0.0;
        wd_output.dumpable_magnitude_nms = 0.0;
        wd_output.saturation_mask = 0U;
        return;
    }
}

// 4. Compute Momentum
adcs_status_t stat = adcs_wheel_momentum(wd_input.wheels, 4, &wd_output.momentum_nms);
if (stat != ADCS_OK) {
    wd_state.mode = WD_FAULT;
    wd_output.momentum_nms.x = 0.0; wd_output.momentum_nms.y = 0.0; wd_output.momentum_nms.z = 0.0;
    wd_output.parallel_momentum_nms.x = 0.0; wd_output.parallel_momentum_nms.y = 0.0; wd_output.parallel_momentum_nms.z = 0.0;
    wd_output.dumpable_momentum_nms.x = 0.0; wd_output.dumpable_momentum_nms.y = 0.0; wd_output.dumpable_momentum_nms.z = 0.0;
    wd_output.dipole_a_m2.x = 0.0; wd_output.dipole_a_m2.y = 0.0; wd_output.dipole_a_m2.z = 0.0;
    wd_output.torque_nm.x = 0.0; wd_output.torque_nm.y = 0.0; wd_output.torque_nm.z = 0.0;
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.saturation_mask = 0U;
    return;
}

// Decompose Momentum
double b_dot_b = adcs_vec3_dot(wd_input.field_body_t, wd_input.field_body_t);
double h_dot_b = adcs_vec3_dot(&wd_output.momentum_nms, wd_input.field_body_t);
double parallel_scale = h_dot_b / b_dot_b;

wd_output.parallel_momentum_nms = adcs_vec3_scale(wd_input.field_body_t, parallel_scale);
wd_output.dumpable_momentum_nms = adcs_vec3_sub(&wd_output.momentum_nms, &wd_output.parallel_momentum_nms);
wd_output.dumpable_magnitude_nms = adcs_vec3_norm(&wd_output.dumpable_momentum_nms);

// 5. State Machine Logic
switch (wd_state.mode) {
    case WD_OFF:
    case WD_ARMING:
        if (wd_output.dumpable_magnitude_nms >= wd_config.start_nms) {
            wd_state.high_cycles++;
        } else {
            wd_state.high_cycles = 0;
        }

        if (wd_state.high_cycles >= wd_config.required_high) {
            wd_state.mode = WD_DUMPING;
            wd_state.high_cycles = 0;
            wd_state.low_cycles = 0;
            wd_state.elapsed = 0;
        }

        wd_output.dipole_a_m2.x = 0.0; wd_output.dipole_a_m2.y = 0.0; wd_output.dipole_a_m2.z = 0.0;
        wd_output.torque_nm.x = 0.0; wd_output.torque_nm.y = 0.0; wd_output.torque_nm.z = 0.0;
        wd_output.saturation_mask = 0U;
        break;

    case WD_DUMPING:
        wd_state.elapsed++;

        adcs_actuator_command_t cmd;
        adcs_vec3_t achievable_torque;
        stat = adcs_momentum_unload_dipole(
            &wd_output.dumpable_momentum_nms,
            wd_input.field_body_t,
            wd_config.gain_s_inv,
            wd_config.max_dipole_a_m2,
            &cmd,
            &achievable_torque
        );

        wd_output.dipole_a_m2 = cmd.command;
        wd_output.torque_nm = achievable_torque;
        wd_output.saturation_mask = cmd.saturated_axes;

        if (wd_state.elapsed >= wd_config.minimum_dump_cycles) {
            if (wd_output.dumpable_magnitude_nms <= wd_config.stop_nms) {
                wd_state.low_cycles++;
            } else {
                wd_state.low_cycles = 0;
            }

            if (wd_state.low_cycles >= wd_config.required_low) {
                wd_state.mode = WD_COOLDOWN;
                wd_state.high_cycles = 0;
                wd_state.low_cycles = 0;
                wd_state.elapsed = 0;
            }
        }
        break;

    case WD_COOLDOWN:
        wd_state.elapsed++;

        wd_output.dipole_a_m2.x = 0.0; wd_output.dipole_a_m2.y = 0.0; wd_output.dipole_a_m2.z = 0.0;
        wd_output.torque_nm.x = 0.0; wd_output.torque_nm.y = 0.0; wd_output.torque_nm.z = 0.0;
        wd_output.saturation_mask = 0U;

        if (wd_state.elapsed >= wd_config.cooldown_cycles) {
            wd_state.mode = WD_OFF;
            wd_state.high_cycles = 0;
            wd_state.low_cycles = 0;
            wd_state.elapsed = 0;
        }
        break;

    case WD_FAULT:
        wd_output.dipole_a_m2.x = 0.0; wd_output.dipole_a_m2.y = 0.0; wd_output.dipole_a_m2.z = 0.0;
        wd_output.torque_nm.x = 0.0; wd_output.torque_nm.y = 0.0; wd_output.torque_nm.z = 0.0;
        wd_output.saturation_mask = 0U;
        break;
}

