int enable_valid = (wd_input.enable == 0 || wd_input.enable == 1);
int wheels_valid = (wd_input.wheels != NULL && wd_input.wheel_count == 4);
int field_valid = 0;
double b_norm_sq = 0.0;
if (wd_input.field_body_t != NULL) {
    b_norm_sq = adcs_vec3_dot(wd_input.field_body_t, wd_input.field_body_t);
    field_valid = (isfinite(b_norm_sq) && b_norm_sq > ADCS_EPS_NORM * ADCS_EPS_NORM);
}

