                   isfinite(wd_config.gain_s_inv) && isfinite(wd_config.max_dipole_a_m2) &&
                   isfinite(wd_config.max_wheel_speed_rad_s) &&
                   wd_config.start_nms >= 0.0 && wd_config.stop_nms >= 0.0 &&
                   wd_config.gain_s_inv >= 0.0 && wd_config.max_dipole_a_m2 >= 0.0 &&
                   wd_config.max_wheel_speed_rad_s > 0.0 &&
                   wd_config.stop_nms < wd_config.start_nms;

unint32 cycles_valid = (wd_config.required_high >= 1 && wd_config.required_high <= 100) &&
                        (wd_config.required_low >= 1 && wd_config.required_low <= 100) &&
                        (wd_config.minimum_dump_cycles >= 1 && wd_config.minimum_dump_cycles <= 100) &&
                        (wd_config.cooldown_cycles >= 1 && wd_config.cooldown_cycles <= 100);

