    wd_output.high_cycles = 0;
    wd_output.low_cycles = 0;
    wd_output.elapsed = 0;
    wd_output.saturation_mask = 0;
    return;
}

// 3. Decompose Momentum
double b2 = adcs_vec3_dot(wd_input.field_body_t, wd_input.field_body_t);
double parallel_scalar = adcs_vec3_dot(&wd_output.momentum_nms, wd_input.field_body_t) / b2;
adcs_vec3_t parallel_part = adcs_vec3_scale(wd_input.field_body_t, parallel_scalar);
wd_output.parallel_momentum_nms = parallel_part;
wd_output.dumpable_momentum_nms = adcs_vec3_sub(&wd_output.momentum_nms, &parallel_part);
wd_output.dumpable_magnitude_nms = adcs_vec3_norm(&wd_output.dumpable_momentum_nms);

// 4. State Machine Logic
// Initialize/reset counters if transitioning to OFF, ARMING (from OFF), DUMPING, COOLDOWN
// Note: wd_state.mode holds the PREVIOUS mode.

wd_mode_t prev_mode = wd_state.mode;

// Default to maintaining current mode unless transition happens
wd_mode_t next_mode = wd_state.mode;

// Handle transitions based on previous mode
if (prev_mode == WD_OFF || prev_mode == WD_ARMING) {
    // Check high condition
    if (wd_output.dumpable_magnitude_nms >= wd_config.start_nms) {
        wd_state.high_cycles++;
    } else {
        wd_state.high_cycles = 0;
    }

    if (wd_state.high_cycles >= wd_config.required_high) {
        next_mode = WD_DUMPING;
        wd_state.low_cycles = 0;
        wd_state.elapsed = 0;
    }
} else if (prev_mode == WD_DUMPING) {
    // Increment elapsed if not the entry call
    // But wait, how do we know if it's the entry call?
    // The entry call sets elapsed to 0.
    // If we are in DUMPING now, and we just entered, elapsed is 0.
    // On subsequent calls, we increment elapsed FIRST.

    // However, the logic for exiting DUMPING depends on elapsed.
    // "DUMPING counts low evidence only on calls where elapsed >= minimum_dump_cycles"

    // If this is the first call in DUMPING (elapsed was 0 from entry), we don't increment yet?
    // "On each later accepted call ... elapsed is incremented first"
    // So if elapsed == 0, it's the entry call. We do NOT increment.
    // If elapsed > 0, we increment.

    if (wd_state.elapsed > 0) {
        wd_state.elapsed++;
    }

    // Check exit condition
    if (wd_state.elapsed >= wd_config.minimum_dump_cycles) {
        if (wd_output.dumpable_magnitude_nms <= wd_config.stop_nms) {
            wd_state.low_cycles++;
        } else {
            wd_state.low_cycles = 0;
        }

        if (wd_state.low_cycles >= wd_config.required_low) {
            next_mode = WD_COOLDOWN;
            wd_state.elapsed = 0; // Reset for COOLDOWN entry
            // High cycles reset on entering COOLDOWN too
            wd_state.high_cycles = 0;
        }
    }
} else if (prev_mode == WD_COOLDOWN) {
    if (wd_state.elapsed > 0) {
        wd_state.elapsed++;
    }

    if (wd_state.elapsed >= wd_config.cooldown_cycles) {
        next_mode = WD_OFF;
        wd_state.high_cycles = 0;
        wd_state.low_cycles = 0;
        wd_state.elapsed = 0;
    }
} else if (prev_mode == WD_FAULT) {
    // Stay in fault
    next_mode = WD_FAULT;
}

// Update state
wd_state.mode = next_mode;
wd_output.mode = next_mode;

// If we just entered a new mode, ensure elapsed is published as 0 for that frame
// This is handled by the fact that we set elapsed=0 on entry, and don't increment on entry.

// 5. Generate Commands
wd_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
wd_output.torque_nm = (adcs_vec3_t){0, 0, 0};
wd_output.saturation_mask = 0;

if (next_mode == WD_DUMPING) {
    adcs_actuator_command_t cmd;
    adcs_status_t cmd_status = adcs_momentum_unload_dipole(
        &wd_output.dumpable_momentum_nms,
        wd_input.field_body_t,
        wd_config.gain_s_inv,
        wd_config.max_dipole_a_m2,
        &cmd,
        &wd_output.torque_nm
    );
    wd_output.dipole_a_m2 = cmd.command;
    wd_output.saturation_mask = cmd.saturated_axes;
}
// OFF, ARMING, COOLDOWN produce zero commands/torques

// 6. Output Assignment
// Most fields already assigned or calculated above.
wd_output.high_cycles = wd_state.high_cycles;
wd_output.low_cycles = wd_state.low_cycles;
wd_output.elapsed = wd_state.elapsed;

